SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(d),'object',to_jsonb(pg_identify_object(d.classid,d.objid,d.objsubid)),'reference',to_jsonb(pg_identify_object(d.refclassid,d.refobjid,d.refobjsubid)),'object_address',to_jsonb(pg_identify_object_as_address(d.classid,d.objid,d.objsubid)),'reference_address',to_jsonb(pg_identify_object_as_address(d.refclassid,d.refobjid,d.refobjsubid))) ORDER BY d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.refobjsubid,d.deptype),'[]'::jsonb) AS payload FROM pg_depend d) AS capture